r['recipe'].append({"order":n,"stage":"statistical_analysis","description":"Q5: (1) q5a_cache.py caches native 0.25\" Xb4b HCN/HCO+ 3-2 cubes (+-6\") with per-pixel linear baselines; (2) q5b_maps.py moment 0/1/2 maps (2.5 sigma channel mask) and local maxima; (3) q5c_clumps.py HCN-HCO+ high-pass cross-correlation and matched-maximum census against shifted-map nulls; (4) q5d_fits.py beam-deconvolved 1-2 component Gaussian fits of HCN, HCO+ and 1.1 mm continuum at N, S, Bridge for several fit radii, Condon errors, line-continuum offsets; (5) q5e_kin.py per-pixel Gaussian fits (v, sigma), planar gradients, peak-pixel and aperture line widths; (6) q5f_rot.py rotation curves along the kinematic axes and enclosed masses with Sakamoto+2014 inclinations; (7) q5g_summary.py sub-clump fits, offsets table, virial masses; (8) build_report_q5.py.",
 "software":"numpy, scipy (least_squares, curve_fit, ndimage), astropy, pandas, matplotlib","parameters":[A("moment window","2430-3130 km/s (2780+-350)"),A("channel mask for m1/m2","3-channel boxcar >2.5 sigma, dilated 1 channel"),A("pixel fits","every 2nd pixel (0.094\"), peak S/N>5, sigma_v error<25 km/s, sigma<250 km/s"),A("fit radii","0.4-2.5\" around each nucleus"),A("rotation bins","+-0.125\" about R, slit half-width 0.25\", PA = measured gradient axis +-15 deg")],
 "scripts":["scripts/q5a_cache.py","scripts/q5b_maps.py","scripts/q5c_clumps.py","scripts/q5d_fits.py","scripts/q5e_kin.py","scripts/q5f_rot.py","scripts/q5g_summary.py","scripts/q5lib.py","scripts/build_report_q5.py"]})
if 'Q5 round' not in r['interpretation']:
    r['interpretation']+=" [Q5 round] At 0.24\" the N nucleus is a ~100 pc dense core inside a 290x70 pc ridge (PA ~112 deg) with a rotation curve flat at ~110-135 km/s (i=30 deg) and enclosed mass ~5e8 Msun within 190 pc; the S nucleus is a compact (~80 pc) core with an E-W edge-on disk (rotation ~55-60 km/s projected, M(<190 pc) ~1e8 Msun, N/S ~4). Virial and rotation masses agree, kinematic axes and their swing with radius match Sakamoto+2014, line centroids coincide with the continuum within <=2 sigma, and HCN is more extended than HCO+ at S and N. These measurements support the beam-filling inputs of the RADEX work only with HCN-HCO+ size differences of 1.2-1.8x allowed."
cav="Q5: (a) Xb4b recovers ~0.5 of the flux, so sizes are of the compact component and sub-clump counts depend on uv sampling (matched-in-both-lines clumps are real, single-line maxima are not); (b) moment-0 window noise is dominated by real structure/uv sampling (0.12 vs thermal 0.01 Jy/b km/s), so Gaussian-fit errors use the residual rms; (c) N is not a single Gaussian (size grows by 1.5-2.5x with fit radius); S continuum is only marginally resolved (0.2\"); (d) masses use inclinations (N 30, S 80 deg) from Sakamoto+2014, not measured here: N mass scales as 1/sin^2 i (x2.1 at 20 deg) and S has no clean rotation law inside 0.3\"; (e) virial masses assume virialised gas and 1/r profile and include any stellar mass; (f) clean beam is Gaussianised (the Xb4b PSF has side lobes), which can bias deconvolved sizes <~0.05\"; (g) fits in the channel-masked m1/m2 maps are not used for numbers (only per-pixel Gaussian fits)."
if isinstance(r['caveats'],list):
    r['caveats']=[c for c in r['caveats'] if not c.startswith('Q5:')]+[cav]
for x in r['results']:
    if x['confidence'] not in ('high','medium','low','tentative'): x['confidence']='low'
json.dump(r,open(p,'w'),indent=1); print(len(r['results']))
